const menu=document.querySelector('.menu-toggle'),nav=document.querySelector('nav');menu.addEventListener('click',()=>{const opened=nav.classList.toggle('open');menu.setAttribute('aria-expanded',String(opened));menu.setAttribute('aria-label',opened?'Close menu':'Open menu');menu.textContent=opened?'×':'☰'});
document.querySelector('#contact-form').addEventListener('submit',event=>{event.preventDefault();const data=new FormData(event.target);const text=['MK LEISURE — CONTACT ENQUIRY','',...['name','email','phone','boat','timeline','budget','vision'].map(key=>`${key[0].toUpperCase()+key.slice(1)}: ${data.get(key)||'Not provided'}`),'','This enquiry has been prepared for sharing and has not been sent.'].join('\n');const url=URL.createObjectURL(new Blob([text],{type:'text/plain;charset=utf-8'}));const link=document.createElement('a');link.href=url;link.download='mk-leisure-contact-enquiry.txt';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);document.querySelector('#contact-status').textContent='Your enquiry is ready to download. Share it with the MK Leisure team to start your journey.'});
